<style>
.rb-program-workspace{color:#24204f;gap:22px;height:auto!important;padding:4px 0 24px;min-width:0}
.rb-program-workspace .rb-workspace-header{border:1px solid #e9e5f4;border-radius:20px;padding:24px 24px 14px;background:linear-gradient(120deg,#fff 60%,#faf6ff);box-shadow:0 2px 8px #24204f04}
.rb-program-workspace .rb-workspace-header>div:first-child{display:flex;flex-wrap:wrap;align-items:center;gap:20px;margin-bottom:24px}
.rb-program-workspace .rb-workspace-header h1{font-size:24px;letter-spacing:-.5px;line-height:1.3;color:#24204f;margin-top:8px}
.rb-program-workspace .rb-workspace-description{font-size:13px;color:#86819b;margin-top:8px}
.rb-program-workspace .rb-workspace-header>div>div:last-child{flex-wrap:wrap}
.rb-program-workspace .rb-workspace-tabs{display:flex;gap:6px;overflow-x:auto;padding:5px 0 2px;margin:0;scrollbar-width:thin;scrollbar-color:#ddd2f5 transparent}
.rb-program-workspace .rb-workspace-tabs a{display:inline-flex;align-items:center;justify-content:center;gap:7px;flex:0 0 auto;padding:11px 13px;border-radius:11px;border:1px solid transparent;font-size:12px;font-weight:600;color:#78728c;text-decoration:none;line-height:18px;background:transparent;transition:background .15s,color .15s}
.rb-program-workspace .rb-workspace-tabs svg{display:block;flex-shrink:0}
.rb-program-workspace .rb-workspace-tabs a:hover{background:#f4edff;color:#8234d5}
.rb-program-workspace .rb-workspace-tabs a[aria-current="page"]{background:#f0e4ff;color:#8425d8!important;border-color:#e7d3ff;box-shadow:none}
.rb-program-workspace .rb-workspace-panels{overflow:visible}
.rb-program-workspace .rb-workspace-panels>div{padding:0;max-width:960px;width:100%;margin-left:auto;margin-right:auto}
.rb-program-workspace .rb-workspace-panels form.rounded-xl{border:1px solid #e8e3f1;border-radius:20px;overflow:hidden;box-shadow:0 3px 12px #24204f05}
.rb-program-workspace .rb-workspace-panels form.rounded-xl>div.p-6{padding:28px 32px}
.rb-program-workspace .rb-details-heading{padding-bottom:6px}
.rb-program-workspace .rb-details-heading h2{font-size:17px;letter-spacing:-.2px}
.rb-program-workspace .rb-details-heading p{font-size:13px;color:#89839b;margin-top:6px}
.rb-program-workspace label{font-size:12px;font-weight:600;color:#625b78;margin-bottom:7px}
.rb-program-workspace .input{border:1px solid #e2ddeb;border-radius:11px;background:#fcfbfe;color:#36304f;min-height:44px;padding:11px 13px;font-size:14px;box-shadow:none;transition:border-color .15s,box-shadow .15s}
.rb-program-workspace .input:hover{border-color:#cfc2e4}
.rb-program-workspace .input:focus{outline:none;border-color:#a855f7;box-shadow:0 0 0 3px #a855f718;background:white}
.rb-program-workspace textarea.input{min-height:88px;resize:vertical}
.rb-program-workspace textarea[name="full_description"]{min-height:130px}
.rb-program-workspace select.input{padding-right:36px}
.rb-program-workspace .btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border-radius:11px;padding:10px 16px;font-size:13px;font-weight:600;line-height:20px;border:1px solid #e4dded;background:white;color:#66597e;text-decoration:none;transition:background .15s,box-shadow .15s}
.rb-program-workspace .btn:hover{background:#f7f2ff;border-color:#d7c4ed}
.rb-program-workspace .btn.btn-primary{background:#8b19df;border-color:#8b19df;color:white;box-shadow:0 3px 8px #8b19df15}
.rb-program-workspace .btn.btn-primary:hover{background:#7611c4;border-color:#7611c4}
.rb-program-workspace .btn:focus-visible,.rb-program-workspace .rb-workspace-tabs a:focus-visible{outline:3px solid #cba2f5;outline-offset:3px}
.rb-program-workspace .btn:disabled{opacity:.55;cursor:wait}
.rb-program-workspace .rb-workspace-panels form>div.bg-gray-50{background:#fcfaff;border-top:1px solid #f0eaf7;padding:18px 32px}
.rb-program-workspace input[type="radio"],.rb-program-workspace input[type="checkbox"]{accent-color:#8b19df}
@media(max-width:767px){.rb-program-workspace{gap:16px}.rb-program-workspace .rb-workspace-header{padding:18px 16px 12px;border-radius:16px}.rb-program-workspace .rb-workspace-header h1{font-size:21px}.rb-program-workspace .rb-workspace-header>div:first-child{margin-bottom:15px;gap:14px}.rb-program-workspace .rb-workspace-panels form.rounded-xl>div.p-6{padding:22px 18px}.rb-program-workspace .rb-workspace-panels form>div.bg-gray-50{padding:16px 18px}.rb-program-workspace .rb-workspace-tabs a{padding:10px 12px}.rb-program-workspace .rb-workspace-panels form.rounded-xl{border-radius:16px}}
@media(prefers-reduced-motion:reduce){.rb-program-workspace *{transition:none!important}}
</style>
